import { 
  LayoutDashboard, 
  ClipboardList, 
  History, 
  BellRing, // Ikon untuk Notifikasi
  LogOut,
  Hospital
} from "lucide-react";
import Link from "next/link";
import { usePathname } from "next/navigation";

export default function Sidebar() {
  const pathname = usePathname();

  const menuItems = [
    {
      title: "Dashboard",
      icon: <LayoutDashboard size={20} />,
      href: "/dashboard/perawat",
    },
    {
      title: "Form Surveilans",
      icon: <ClipboardList size={20} />,
      href: "/dashboard/perawat/form",
    },
    {
      title: "Riwayat Saya",
      icon: <History size={20} />,
      href: "/dashboard/perawat/riwayat",
    },
    {
      title: "Notifikasi", // Modul Ambang Batas (Alert System)
      icon: <BellRing size={20} />,
      href: "/dashboard/perawat/notifikasi",
      badge: true, // Opsional: Indikator jika ada High Alert
    },
  ];

  return (
    <aside className="w-64 h-screen bg-white border-r border-slate-100 flex flex-col fixed left-0 top-0 z-50">
      {/* Brand Logo */}
      <div className="p-6 border-b border-slate-50 flex items-center gap-3">
        <div className="w-10 h-10 bg-blue-600 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-blue-100">
          <Hospital size={24} />
        </div>
        <div>
          <h1 className="text-sm font-bold text-slate-800 leading-none">RS ARUN</h1>
          <p className="text-[10px] font-medium text-slate-400 mt-1 uppercase tracking-widest">Lhokseumawe</p>
        </div>
      </div>

      {/* Main Menu */}
      <nav className="flex-1 p-4 space-y-2 mt-4">
        <p className="px-4 text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em] mb-4">Main Menu</p>
        
        {menuItems.map((item) => {
          const isActive = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`flex items-center justify-between px-4 py-3 rounded-2xl transition-all group ${
                isActive 
                ? "bg-blue-600 text-white shadow-lg shadow-blue-100 font-semibold" 
                : "text-slate-500 hover:bg-slate-50 font-medium"
              }`}
            >
              <div className="flex items-center gap-3">
                <span className={`${isActive ? "text-white" : "text-slate-400 group-hover:text-blue-500"}`}>
                  {item.icon}
                </span>
                <span className="text-sm">{item.title}</span>
              </div>
              
              {/* Badge High Alert khusus menu Notifikasi */}
              {item.badge && (
                <span className={`w-2 h-2 rounded-full animate-pulse ${isActive ? "bg-white" : "bg-red-500"}`} />
              )}
            </Link>
          );
        })}
      </nav>

      {/* Footer / Logout */}
      <div className="p-4 border-t border-slate-50">
        <button className="w-full flex items-center gap-3 px-4 py-3 text-slate-500 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all font-medium text-sm">
          <LogOut size={20} />
          <span>Keluar</span>
        </button>
      </div>
    </aside>
  );
}